      const chosen = typeof facts.chosen === "string" && facts.chosen !== "" ? facts.chosen : null;
      const others = (Array.isArray(facts.candidates) ? facts.candidates : []).filter((candidate) => candidate !== chosen);
      const tail = others.length > 0 ? `. The ${others.length === 1 ? "job" : "jobs"} abloh could ride instead ${others.length === 1 ? "is" : "are"} ${quoted3([...others])}` : chosen === null ? ". abloh read no job it could ride instead" : "";
